    def process_order(self, order, engine, entrust_callback_func, need_max_entrade_get=True, strategyfare_id=''):
        entrust_prop = None
        entrust_price = None
        if order.type == 'TRADE_MARKET':
            entrust_prop = MARKET_TYPE[str(order._style.market_type)]
            entrust_price = round(float(order._style.limit_price), 3)
        iqd_stock_code = order.symbol.replace('XSHG', 'SS').replace('XSHE', 'SZ')
        if iqd_stock_code.endswith('SS'):
            exchange_type = '1'
        elif iqd_stock_code.endswith('SZ'):
            exchange_type = '2'
        else:
            return ({'error_no': -1, 'error_info': '不支持的代码类型【%s】' % iqd_stock_code}, None)
        entrust_amount = order.amount
        if iqd_stock_code in NATIONAL_DEBT_LIST:
            entrust_prop = '4'
        if entrust_price is None:
            entrust_price = round(float(order.price), 3)
        if entrust_price == 0:
            snp = engine.data_proxy.get_snapshot(iqd_stock_code)
            if not (snp and snp[iqd_stock_code]):
                return ({'error_no': -1, 'error_info': '代码【%s】实时行情获取失败' % iqd_stock_code}, None)
            elif order.type == 'GEAR':
                entrust_price = gear_price_handle(order, snp, iqd_stock_code)
            else:
                entrust_price = snp[iqd_stock_code].get('last_px', 1)
        if order.entrust_direction == EntrustDirection.BUY:
            entrust_bs = '1'
        elif order.entrust_direction == EntrustDirection.SELL:
            entrust_bs = '2'
        else:
            return ({'error_no': -1, 'error_info': '不支持的委托方向类型'}, None)
        entrust_price = round(float(entrust_price), 3)
        if not entrust_prop:
            kwargs = {'exchange_type': exchange_type, 'business_type': 'stock', 'entrust_bs': entrust_bs, 'stock_code': iqd_stock_code.split('.')[0], 'entrust_price': entrust_price}
        else:
            kwargs = {'exchange_type': exchange_type, 'business_type': 'stock', 'entrust_bs': entrust_bs, 'stock_code': iqd_stock_code.split('.')[0], 'entrust_price': entrust_price, 'entrust_prop': entrust_prop}
        kwargs['entrust_amount'] = entrust_amount
        kwargs['is_async'] = True
        kwargs['func'] = entrust_callback_func
        kwargs['order'] = order
        kwargs['entrust_reference'] = str(order.entrust_reference)
        kwargs['strategyfare_id'] = str(strategyfare_id)
        system_log.debug(f"委托处理结束，发送订单，order_id：{order.order_id!s}，代码：{order.symbol!s}，当前时间：{datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S.%f')!s}")
        return self.trade_account.security_entrust(**(kwargs))
    def cancel_order(self, order, cancel_callback_func):
        exchange_type = ''
        iqd_stock_code = order.symbol.replace('XSHG', 'SS').replace('XSHE', 'SZ')
        if iqd_stock_code.endswith('SS'):
            exchange_type = '1'
        elif iqd_stock_code.endswith('SZ'):
            exchange_type = '2'
        entrust_no = order.entrust_no
        kwargs = dict()
        entrust_date = datetime.datetime.now().strftime('%Y%m%d')
        error_dict, response = self.trade_account.security_withdraw(exchange_type=exchange_type, entrust_no=entrust_no, entrust_date=entrust_date, **(kwargs))
        return (error_dict, response)
    def rzrq_cancel_order(self, order):
        exchange_type = ''
        iqd_stock_code = order.symbol.replace('XSHG', 'SS').replace('XSHE', 'SZ')
        if iqd_stock_code.endswith('SS'):
            exchange_type = '1'
        elif iqd_stock_code.endswith('SZ'):
            exchange_type = '2'
        entrust_no = order.entrust_no
        error_dict, response = self.trade_account.func_secu_rzrq_entrust_withdraw(exchange_type=exchange_type, entrust_no=entrust_no, business_type='rzrq', asset_prop='7')
        return (error_dict, response)
    def entrust_rsp(self, event, order, is_cancel=False):
        entrust_rsp_handle(self.engine, order, event, is_cancel=is_cancel)
